Überblick pro Produkt im Zwischenspeicher (6 Stunden): «Analyse starten», «Zustand prüfen» und der Ricardo-Text brauchen ihn je neu, und er kostet sonst mehrere Sekunden (Recherche suchen, Handbuch-Sheet öffnen). Der Schlüssel enthält die Produktzeile: Ändert sie (z.B. Recherche fertig), gilt der alte nicht mehr. Änderungen, die alle Produkte betreffen (Einstellungen, Stufen, Testmittel, Handbücher), machen über uebNeu_ alle ungültig. Der Abgleich wärmt die Warteschlange vor. /
const UEB_TTL = 21600;
function uebNeu_() { try { CacheService.getScriptCache().put('ueb-gen', String(Date.now()), UEB_TTL); } catch (err) { /* läuft ab */ } }
function uebSchluessel_(p, gen) {
  const s = JSON.stringify(p);
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
